import{_ as t,o as a,c as i,ak as n}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"GDD directory and v2 update notes","description":"Updated October 23, 2026. Edit only game-design.md. Its two PDFs are generated views of the same adopted design, not independent specifications.","frontmatter":{"title":"GDD directory and v2 update notes","description":"Updated October 23, 2026. Edit only game-design.md. Its two PDFs are generated views of the same adopted design, not independent specifications.","source":"docs/gdd-template-editions.md","category":"Other documents","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/gdd-template-editions.md","filePath":"content/docs/gdd-template-editions.md"}'),o={name:"content/docs/gdd-template-editions.md"};function d(r,e,s,c,l,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<div><h1 id="gdd-directory-and-v2-update-notes">GDD directory and v2 update notes<a class="header-anchor" href="#gdd-directory-and-v2-update-notes" aria-label="Link to this section">​</a></h1><p>Updated October 23, 2026. <strong>Edit only <a href="/Chainy-Docs/content/docs/game-design.html">game-design.md</a></strong>. Its two PDFs are generated views of the same adopted design, not independent specifications.</p><h2 id="current-design">Current design<a class="header-anchor" href="#current-design" aria-label="Link to this section">​</a></h2><table><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/Chainy-Docs/content/docs/game-design.html">Canonical GDD v2 — Markdown</a></td><td>Complete adopted gameplay, quests, mechanics, concepts, visuals, acceptance and delivery boundaries</td></tr><tr><td><a href="/Chainy-Docs/attachments/output/pdf/Chainy-GDD-v2-Gameplay-First-Reference-Format.pdf">V2 reference-format PDF</a></td><td>Illustrated reading edition</td></tr><tr><td><a href="/Chainy-Docs/attachments/output/pdf/Chainy-GDD-v2-Gameplay-First-Implementation-Format.pdf">V2 implementation-format PDF</a></td><td>Same substantive design in the second presentation style; no additional implemented features</td></tr><tr><td><a href="/Chainy-Docs/content/docs/game-design-v2-gameplay-first.html">Former v2 source path</a></td><td>Redirect note to the canonical source; do not maintain another copy</td></tr><tr><td><a href="/Chainy-Docs/content/docs/media/gdd/gameplay-first/readme.html">Gameplay-first visual pack</a></td><td>Concept illustrations and production limitations, not gameplay screenshots/assets</td></tr></tbody></table><h2 id="gdd-v2-update-notes">GDD v2 update notes<a class="header-anchor" href="#gdd-v2-update-notes" aria-label="Link to this section">​</a></h2><p>Compared with the October 22 mini-game-first GDD and its two template PDFs:</p><ul><li>Added a sequential Web3 → Blockchain → AI island-restoration adventure with visible world changes and completed-area revisits.</li><li>Added a 20-quest full roadmap: eight Web3, seven Blockchain and five AI quests, with explicit core/stretch/later gates.</li><li>Added one persistent lantern purchase connecting fictional economy, ownership and Blockchain record repair.</li><li>Added quest prerequisites, report-back states, retained early pickups, one-time rewards, inventory, balances and restoration flags.</li><li>Added wallet review → authorization → confirmation, free cancellation and atomic, repeat-safe saves.</li><li>Added three-block reconstruction from a trusted checkpoint and altered-record rejection; this is a distinct activity, not BlockMatch.</li><li>Added optional actual example-trained AI classification, separate practice and reserved final cases; retained authored assistant verification and supervised dispatch for later.</li><li>Added chronological quest log and encyclopedia progress labels: Discovered, Explained, Practiced and Demonstrated.</li><li>Expanded SQLite requirements to preserve the gameplay economy, records, quests and checkpoints together.</li><li>Established Sean, Matthew and Lee as the three guides, reusing the robot family.</li><li>Retained all twelve concepts in the full product, while narrowing the beta to W01–W04 and B01–B03/demo B07.</li><li>Deferred standalone Wordle and BlockMatch; contextual Quiz supports the core. Deferred teacher provisioning, pairing, dashboard, collection/upload and distribution behind gameplay.</li><li>Clarified a personal-phone full-product model and honest local demo profiles for beta.</li><li>Added recovery rules, detailed acceptance scenarios and scope/capacity gates.</li></ul><p>The fixed isometric low-poly direction and live-world dialogue overlay were already adopted before v2; they are <strong>retained</strong>, not new v2 features. V2 contains design intentions, not evidence of implementation.</p><p><strong>October 23 decision update:</strong> v2 adopted; <strong>Cryptita Plays community beta testing moves to November 10, 2026</strong>, replacing the Marinduque school event. <strong>Pre-final stays November 21</strong>. These confirmations supersede the review draft&#39;s open schedule/adoption questions.</p><h2 id="historical-gdds--archived-not-active-requirements">Historical GDDs — archived, not active requirements<a class="header-anchor" href="#historical-gdds--archived-not-active-requirements" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Edition</th><th>Markdown / PDF</th></tr></thead><tbody><tr><td>October 8 original bounded-learning design</td><td><a href="/Chainy-Docs/content/docs/archive/pre-2026-10-12/docs/game-design.html">Markdown</a> · <a href="/Chainy-Docs/attachments/docs/archive/pre-v2-adoption-2026-10-23/output/pdf/Chainy-Illustrated-GDD.pdf">14-page illustrated PDF</a></td></tr><tr><td>Pre-v2 mini-game-first design</td><td><a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/game-design.html">Markdown snapshot</a> · <a href="/Chainy-Docs/attachments/docs/archive/pre-v2-adoption-2026-10-23/output/pdf/Chainy-GDD-Example-Format.pdf">10-page example PDF</a> · <a href="/Chainy-Docs/attachments/docs/archive/pre-v2-adoption-2026-10-23/output/pdf/Chainy-GDD-Template-Format.pdf">8-page template PDF</a></td></tr><tr><td>October 22 v2 review proposal</td><td><a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/game-design-v2-gameplay-first.html">Original Markdown</a> · <a href="/Chainy-Docs/attachments/docs/archive/pre-v2-adoption-2026-10-23/output/pdf/Chainy-GDD-v2-Gameplay-First-Reference-Format.pdf">Reference PDF</a> · <a href="/Chainy-Docs/attachments/docs/archive/pre-v2-adoption-2026-10-23/output/pdf/Chainy-GDD-v2-Gameplay-First-Implementation-Format.pdf">Implementation PDF</a></td></tr></tbody></table><p>The <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/readme.html">adoption archive</a> also preserves the supporting documents and local tracker snapshots before reconciliation. Original research/source documents remain evidence, not current GDDs. No first-party GDD was found in the Unity project during the inventory; this directory covers the management repository&#39;s authored GDD files.</p></div>',1)])])}const u=t(o,[["render",d]]);export{m as __pageData,u as default};
